import { writeFileSync } from 'node:fs';

const dir = new URL('.', import.meta.url);
const D = '26.1027';
const msgs = {
  1: ['ADD => consigna, datos del manual, esqueleto de diagnose y tests de ejemplo', 'ADD => archivo de exclusiones de git', '- DECISIONES.md queda como plantilla sin completar'],
  2: ['ADD => skill con el formato de commits del proyecto'],
  3: ['ADD => instrucciones compartidas para agentes de IA'],
  4: ['ADD => diagnose con normalización de códigos, notFound, unión de probabilidades en causas compartidas y orden determinista', 'ADD => tests de las reglas de la consigna y de los casos límite'],
  5: ['ADD => las causas sin definición en el manual se informan con el id como respaldo y sin pasos', 'ADD => test de ese caso'],
  6: ['FIX => los pasos del resultado se copian para no compartir referencias con el manual', 'ADD => test de que modificar un resultado no afecta a las siguientes llamadas'],
  7: ['MOD => el desempate entre causas de igual probabilidad compara por código de carácter'],
};
for (const [n, lines] of Object.entries(msgs)) {
  const text = [D, ...lines.map((l) => '    ' + l)].join('\n') + '\n';
  if (!/^[0-9]{2}\.[0-9]{4}\n/.test(text) || /\t|\n\n/.test(text)) throw new Error('mensaje inválido ' + n);
  writeFileSync(new URL(`msg${n}.txt`, dir), text);
}
console.log('ok');

